<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Solicitud de contrato</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-slate-50"><main class="max-w-3xl mx-auto p-5"><h1 class="text-2xl font-bold">Solicitud de contrato</h1><p class="text-sm">Paso {{ array_search($step, array_keys($steps), true) + 1 }} de {{ count($steps) }}: {{ $steps[$step] }}</p><nav class="my-4 flex flex-wrap gap-1 text-xs">@foreach($steps as $key => $label)<a class="px-2 py-1 rounded {{ $key === $step ? 'bg-blue-700 text-white' : 'bg-white' }}" href="{{ route('contrato.solicitud.step', [$public->public_reference, $token, $key]) }}">{{ $loop->iteration }}. {{ $label }}</a>@endforeach</nav>@if($errors->any())<div class="p-3 mb-4 rounded bg-red-50">{{ $errors->first() }}</div>@endif
