enance.exists') }} {{ data_get($payload,'maintenance.payer') }} · {{ data_get($payload,'renewal.is_renewal') }} {{ data_get($payload,'renewal.previous_contract_id') }}</dd></dl><p>No se genera ningún documento automáticamente.</p><form method="POST" action="{{ route('contrato.solicitud.submit', [$public->public_reference, $token]) }}">@csrf<input class="hidden" name="website"><button>Enviar solicitud</button></form></section>
@else<form method="POST" action="{{ route('contrato.solicitud.save', [$public->public_reference, $token, $step]) }}" class="bg-white p-5 rounded shadow">@csrf @method('PUT')<input type="hidden" name="expected_version_id" value="{{ $draft->currentVersion->id }}"><input class="hidden" name="website">
@if($step === 'generales')<label>Fecha<input type="date" name="payload[metadata][contract_date]" value="{{ data_get($payload, 'metadata.contract_date') }}"></label><label>Alias<input name="payload[leased_property][alias]" value="{{ data_get($payload, 'leased_property.alias') }}"></label><label>Domicilio<input name="payload[leased_property][address]" value="{{ data_get($payload, 'leased_property.address') }}"></label>
@elseif(in_array($step, ['arrendador', 'arrendatario'], true))@include('contratos.borradores._wizard_party', ['party' => $step === 'arrendador' ? 'lessor' : 'lessee', 'payload' => $payload])
@elseif($step === 'tercero')<label>Tipo de tercero<select name="payload[guarantor][type]"><option value="none" @selected(data_get($payload, 'guarantor.type') === 'none')>Sin tercero</option><option value="fisica" @selected(data_get($payload, 'guarantor.type') === 'fisica')>Persona física</option><option value="moral" @selected(data_get($payload, 'guarantor.type') === 'moral')>Persona moral</option></select></label>@include('contratos.borradores._wizard_party', ['party' => 'guarantor', 'payload' => array_merge($payload, ['guarantor' => ['person' => data_get($payload, 'guarantor.person', []), 'representative' => data_get($payload, 'guarantor.representative', [])]])])
@elseif($step === 'garantia')<label>¿Inmueble en garantía?<select name="payload[guarantee_property][exists]"><option value="no" @selected(data_get($payload, 'guarantee_property.exists') === 'no')>No</option><option value="yes" @selected(data_get($payload, 'guarantee_property.exists') === 'yes')>Sí</option></select></label><input placeholder="Domicilio de garantía" name="payload[guarantee_property][address]" value="{{ data_get($payload, 'guarantee_property.address') }}"><input placeholder="Título de propiedad" name="payload[guarantee_property][title_deed]" value="{{ data_get($payload, 'guarantee_property.title_deed') }}">
@elseif($step === 'vigencia')@foreach(['start_date','end_date','duration_label'] as $f)<input name="payload[term][{{ $f }}]" value="{{ data_get($payload,'term.'.$f) }}">@endforeach<input name="payload[term][rent_due_rule][raw_text]" value="{{ data_get($payload,'term.rent_due_rule.raw_text') }}">@foreach(['total_rent','monthly_rent','security_deposit','rental_commission','monthly_commission_value'] as $f)<input name="payload[amounts][{{ $f }}]" value="{{ data_get($payload,'amounts.'.$f) }}">@endforeach<select name="payload[amounts][monthly_commission_unit]">@foreach(['unknown','percent','fraction','fixed'] as $v)<option value="{{ $v }}" @selected(data_get($payload,'amounts.monthly_commission_unit')===$v)>{{ $v }}</option>@endforeach</select>
@elseif($step === 'uso')<input type="hidden" name="payload[leased_property][_property_use_codes_submitted]" value="1">@foreach(['residential'=>'Casa habitación','industrial'=>'Industrial','commercial'=>'Comercial','other'=>'Otro'] as $value=>$label)<label><input type="checkbox" name="payload[leased_property][property_use_codes][]" value="{{ $value }}" @checked(in_array($value, data_get($payload, 'leased_property.property_use_codes', []), true))>{{ $label }}</label>@endforeach
@elseif($step === 'pago')<select name="payload[payment][method]">@foreach(['cash'=>'Efectivo','bank_transfer'=>'Transferencia','unspecified'=>'Por definir'] as $v=>$l)<option value="{{ $v }}" @selected(data_get($payload,'payment.method')===$v)>{{ $l }}</option>@endforeach</select><input placeholder="Banco" name="payload[payment][bank_name]" value="{{ data_get($payload,'payment.bank_name') }}"><input placeholder="Beneficiario" name="payload[payment][beneficiary]" value="{{ data_get($payload,'payment.beneficiary') }}"><input placeholder="CLABE" name="payload[payment][clabe]" value="{{ data_get($payload,'payment.clabe') }}">
@elseif($step === 'mantenimiento')<select name="payload[maintenance][exists]"><option value="no" @selected(data_get($payload, 'maintenance.exists') === 'no')>No hay cuotas</option><option value="yes" @selected(data_get($payload, 'maintenance.exists') === 'yes')>Sí hay cuotas</option></select><select name="payload[maintenance][payer]"><option value="" @selected(data_get($payload, 'maintenance.payer') === null)>—</option><option value="lessor" @selected(data_get($payload, 'maintenance.payer') === 'lessor')>Arrendador</option><option value="lessee" @selected(data_get($payload, 'maintenance.payer') === 'lessee')>Arrendatario</option></select>
@elseif($step === 'renovacion')<select name="payload[renewal][is_renewal]"><option value="no" @selected(data_get($payload, 'renewal.is_renewal') === 'no')>No</option><option value="yes" @selected(data_get($payload, 'renewal.is_renewal') === 'yes')>Sí</option></select><input placeholder="Contrato previo (opcional)" name="payload[renewal][previous_contract_id]" value="{{ data_get($payload, 'renewal.previous_contract_id') }}">
@else<p>Completa este bloque y guarda para conservar tu avance.</p>@endif
<button>Guardar</button><button name="next" value="1">Guardar y continuar</button></form>
@endif</main><script>document.addEventListener('DOMContentLoaded',()=>{const t=document.querySelector('[name="payload[guarantor][type]"]'),g=document.querySelector('[name="payload[guarantee_property][exists]"]'),p=document.querySelector('[name="payload[payment][method]"]'),m=document.querySelector('[name="payload[maintenance][exists]"]'),r=document.querySelector('[name="payload[renewal][is_renewal]"]');const toggle=(sel,on)=>document.querySelectorAll(sel).forEach(e=>e.classList.toggle('hidden',!on));const update=()=>{if(t){toggle('[data-party-branch="guarantor"]',t.value!=='none');toggle('[name="payload[guarantee_property][exists]"]',t.value!=='none');}if(g)toggle('[name="payload[guarantee_property][address]"]',g.value==='yes');if(g)toggle('[name="payload[guarantee_property][title_deed]"]',g.value==='yes');if(p)toggle('[name^="payload[payment][bank_"]',p.value==='bank_transfer');if(p)toggle('[name="payload[payment][beneficiary]"]',p.value==='bank_transfer');if(p)toggle('[name="payload[payment][clabe]"]',p.value==='bank_transfer');if(m)toggle('[name="payload[maintenance][payer]"]',m.value==='yes');if(r)toggle('[name="payload[renewal][previous_contract_id]"]',r.value==='yes');};[t,g,p,m,r].filter(Boolean).forEach(e=>e.addEventListener('change',update));update();});</script></body></html>
